from io import StringIO
from unittest.mock import patch

from django.core.management import call_command
from django.db import IntegrityError
from django.test import TestCase

from people.models import Student, User
from timetable.models import Class, ClassStudent


class SeedIGK3StudentsTests(TestCase):
    def seed(self):
        call_command("seed_ig_k3_students", stdout=StringIO())

    def test_creates_complete_students_and_enrollments_without_accounts(self):
        # Bulk creation must populate the fields normally generated by save().
        with patch.object(Student, "save", side_effect=AssertionError("Not bulk")):
            self.seed()
        class_obj = Class.objects.get(
            education_level="IG", cohort_identifier="K", cohort_sub_category="3",
        )
        students = list(Student.objects.all())
        self.assertEqual(len(students), 30)
        self.assertEqual(ClassStudent.objects.filter(class_obj=class_obj).count(), 30)
        self.assertFalse(User.objects.exists())
        self.assertEqual(len({student.check_in_token for student in students}), 30)
        self.assertEqual(len({student.unique_code for student in students}), 30)
        for student in students:
            student.full_clean()
            self.assertIsNotNone(student.dob)
            self.assertIsNotNone(student.enrollment_date)
            self.assertTrue(student.contact.endswith("@example.com"))
            self.assertTrue(student.exam_candidate_number)
            self.assertTrue(student.check_in_token)
            self.assertIsNone(student.user_id)

    def test_rerun_reuses_class_and_preserves_students_and_existing_enrollments(self):
        class_obj = Class.objects.create(
            education_level="IG", cohort_identifier="K", cohort_sub_category="3",
        )
        original = Student.objects.create(name="Existing Student")
        ClassStudent.objects.create(class_obj=class_obj, student=original)
        self.seed()
        before = list(Student.objects.order_by("pk").values())
        ClassStudent.objects.filter(student__unique_code="DUMMY-IGK3-001").delete()
        self.seed()
        self.assertEqual(list(Student.objects.order_by("pk").values()), before)
        self.assertEqual(Class.objects.count(), 1)
        self.assertEqual(ClassStudent.objects.filter(class_obj=class_obj).count(), 31)

    def test_enrollment_failure_rolls_back_students_and_new_class(self):
        with patch.object(ClassStudent.objects, "bulk_create", side_effect=IntegrityError):
            with self.assertRaises(IntegrityError):
                self.seed()
        self.assertFalse(Student.objects.exists())
        self.assertFalse(Class.objects.exists())
